 132:   async initialize(context: common.UIAbilityContext): Promise<boolean> {
 133:     if (this.storeReady) {
 134:       return true;
 135:     }
 136:     this.store.injectContext(context);
 137:     const ok = await this.store.initialize();
 138:     if (!ok) {
 139:       return false;
 140:     }
 141: 
 142:     const settingsJson = await this.store.getSettingsJson();
 143:     if (settingsJson.length > 0) {
 144:       this.settings = WebDavSettings.fromJSON(settingsJson);
 145:       this.settings.remoteRoot = normalizeRoot(this.settings.remoteRoot);
 146:     }
 147: 
 148:     const manifestJson = await this.store.getManifestJson();
 149:     if (manifestJson.length > 0) {
 150:       this.manifest = WebDavManifest.fromJSON(manifestJson, this.manifest.deviceId);
 151:     } else {
 152:       await this.store.saveManifestJson(this.manifest.toJSON());
 153:     }
 154: 
 155:     const snapshotJson = await this.store.getSnapshotJson();
 156:     if (snapshotJson.length > 0) {
 157:       this.lastSnapshotJson = snapshotJson;
 158:     }
 159: 
 160:     this.storeReady = true;
 161:     return true;
 162:   }
