   1: // =====================================================
   2: // WebDavClient.ets - Minimal WebDAV client via @ohos.net.http
   3: // Supports PUT/GET/HEAD/DELETE with Basic Auth.
   4: // =====================================================
   5: 
   6: import http from '@ohos.net.http';
   7: import { Base64Util } from './Base64Util';
   8: 
   9: import type { IWebDavBackend } from './IWebDavBackend';
  10: 
  11: export interface WebDavResponse {
  12:   statusCode: number;
  13:   headers: Record<string, string>;
  14:   body: string;
  15: }
  16: 
  17: interface HttpErrorInfo {
  18:   code: string;
  19:   message: string;
  20: }
  21: 
  22: export class WebDavClient implements IWebDavBackend {
  23:   private endpoint: string;
  24:   private authHeader: string;
  25:   private static readonly MAX_REDIRECTS: number = 2;
  26: 
  27:   constructor(endpoint: string, username: string, password: string) {
  28:     this.endpoint = endpoint.replace(/\/+$/g, '');
  29:     const raw = `${username}:${password}`;
  30:     this.authHeader = `Basic ${Base64Util.encodeUtf8String(raw)}`;
  31:   }
  32: 
  33:   async get(path: string): Promise<WebDavResponse> {
  34:     return this.request(http.RequestMethod.GET, path, {}, undefined);
  35:   }
  36: 
  37:   async head(path: string): Promise<WebDavResponse> {
  38:     return this.request(http.RequestMethod.HEAD, path, {}, undefined);
  39:   }
  40: 
  41:   async put(path: string, body: string, contentType: string = 'application/octet-stream', extraHeaders: Record<string, string> = {}, ensureDir: boolean = true): Promise<WebDavResponse> {
  42:     const headers: Record<string, string> = { 'Content-Type': contentType };
  43:     Object.keys(extraHeaders).forEach((key: string) => {
  44:       headers[key] = extraHeaders[key];
  45:     });
  46: 
  47:     // 自动创建父目录
  48:     if (ensureDir) {
  49:       await this.ensureParentExists(path);
  50:     }
  51: 
  52:     return this.request(http.RequestMethod.PUT, path, headers, body);
  53:   }
  54: 
  55:   private async ensureParentExists(path: string): Promise<void> {
  56:     const lastSlash = path.lastIndexOf('/');
  57:     if (lastSlash <= 0) return;
  58: 
  59:     const parent = path.substring(0, lastSlash);
  60:     if (parent.length === 0 || parent === '/') return;
  61: 
  62:     try {
  63:       const headRes = await this.head(parent);
  64:       if (headRes.statusCode === 404) {
  65:         console.info(`[WebDavClient] Creating parent directory: ${parent}`);
  66:         // 递归创建父目录
  67:         await this.ensureParentExists(parent);
  68:         await this.mkcol(parent);
  69:       }
  70:     } catch (e) {
  71:       // 忽略检查错误，让 PUT 自己失败
  72:       const errMsg = e instanceof Error ? e.message : String(e);
  73:       console.warn(`[WebDavClient] ensureParentExists failed for ${parent}: ${errMsg} (will continue)`);
  74:     }
  75:   }
  76: 
  77:   async delete(path: string): Promise<WebDavResponse> {
  78:     return this.request(http.RequestMethod.DELETE, path, {}, undefined);
  79:   }
  80: 
  81:   async mkcol(path: string): Promise<WebDavResponse> {
  82:     // 使用 PUT 创建目录（WebDAV 服务器通常支持 PUT 到目录路径）
  83:     // 或者尝试 PUT 一个空文件到 .keep 文件来创建目录
  84:     const keepFile = path.endsWith('/') ? `${path}.keep` : `${path}/.keep`;
  85:     return this.request(http.RequestMethod.PUT, keepFile, { 'Content-Type': 'text/plain' }, '');
  86:   }
  87: 
  88:   private buildUrl(path: string): string {
  89:     if (path.startsWith('http://') || path.startsWith('https://')) {
  90:       return path;
  91:     }
  92:     if (!path.startsWith('/')) {
  93:       path = `/${path}`;
  94:     }
  95:     return `${this.endpoint}${path}`;
  96:   }
  97: 
  98:   private normalizeHeaders(headers: Record<string, string | string[] | number | undefined>): Record<string, string> {
  99:     const out: Record<string, string> = {};
 100:     for (const k of Object.keys(headers)) {
 101:       const v = headers[k];
 102:       if (v === undefined) continue;
 103:       if (Array.isArray(v)) {
 104:         out[k.toLowerCase()] = v.join(',');
 105:       } else {
 106:         out[k.toLowerCase()] = String(v);
 107:       }
 108:     }
 109:     return out;
 110:   }
 111: 
 112:   private async request(method: http.RequestMethod, path: string, headers: Record<string, string>, body?: string): Promise<WebDavResponse> {
 113:     const requestId = this.newRequestId();
 114:     return this.requestWithRedirect(method, path, headers, body, WebDavClient.MAX_REDIRECTS, requestId);
 115:   }
 116: 
 117:   private async requestWithRedirect(
 118:     method: http.RequestMethod,
 119:     path: string,
 120:     headers: Record<string, string>,
 121:     body: string | undefined,
 122:     redirectsLeft: number,
 123:     requestId: string
 124:   ): Promise<WebDavResponse> {
 125:     const startMs = Date.now();
 126:     const request = http.createHttp();
 127: 
 128:     const url = this.buildUrl(path);
 129:     // Merge headers manually to avoid spread operator issues
 130:     const allHeaders: Record<string, string> = {
 131:       'Authorization': this.authHeader,
 132:       'Accept': '*/*'
 133:     };
 134:     // Add custom headers
 135:     Object.keys(headers).forEach((key: string) => {
 136:       allHeaders[key] = headers[key];
 137:     });
 138: 
 139:     try {
 140:       const options: http.HttpRequestOptions = {
 141:         method,
 142:         header: allHeaders,
 143:         connectTimeout: 15000,
 144:         readTimeout: 20000
 145:       };
 146:       if (body !== undefined && (method === http.RequestMethod.PUT || method === http.RequestMethod.POST)) {
 147:         options.extraData = body;
 148:       }
 149:       const res = await request.request(url, options);
 150: 
 151:       const statusCode = res.responseCode ?? 0;
 152:       // Ensure res.header is treated as the correct type
 153:       const resHeaders = this.normalizeHeaders(res.header as Record<string, string | string[] | number | undefined>);
 154:       const raw = res.result;
 155:       let bodyStr = '';
 156:       if (typeof raw === 'string') {
 157:         bodyStr = raw;
 158:       } else if (raw instanceof ArrayBuffer) {
 159:         // Decode as UTF-8-ish text (best-effort)
 160:         const bytes = new Uint8Array(raw);
 161:         bodyStr = '';
 162:         for (const b of bytes) bodyStr += String.fromCharCode(b);
 163:       } else {
 164:         bodyStr = '';
 165:       }
 166: 
 167:       request.destroy();
 168:       const elapsed = Date.now() - startMs;
 169:       if (redirectsLeft > 0 && (statusCode === 301 || statusCode === 302 || statusCode === 303 || statusCode === 307 || statusCode === 308)) {
 170:         const location = resHeaders['location'] ?? '';
 171:         console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} (redirect: ${location}) in ${elapsed}ms`);
 172:         if (location.length > 0) {
 173:           return this.requestWithRedirect(method, location, headers, body, redirectsLeft - 1, requestId);
 174:         }
 175:       }
 176:       console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} in ${elapsed}ms`);
 177:       return { statusCode, headers: resHeaders, body: bodyStr };
 178:     } catch (e) {
 179:       request.destroy();
 180:       const err = this.buildHttpErrorInfo(e as (object | string | number | boolean | null | undefined));
 181:       const elapsed = Date.now() - startMs;
 182:       console.error(`[WebDAV] ${String(method)} ${url} - ERROR ${err.code}: ${err.message} (${elapsed}ms)`);
 183:       return { statusCode: 0, headers: {}, body: err.message };
 184:     }
 185:   }
 186: 
 187:   private buildHttpErrorInfo(e: object | string | number | boolean | null | undefined): HttpErrorInfo {
 188:     if (e === null || e === undefined) {
 189:       return { code: '', message: 'unknown_error' };
 190:     }
 191:     if (typeof e === 'string' || typeof e === 'number' || typeof e === 'boolean') {
 192:       return { code: '', message: String(e) };
 193:     }
 194:     if (e instanceof Error) {
 195:       const name = e.name ?? '';
 196:       const msg = e.message ?? '';
 197:       if (name.length > 0 && msg.length > 0) {
 198:         return { code: '', message: `${name}: ${msg}` };
 199:       }
 200:       if (msg.length > 0) {
 201:         return { code: '', message: msg };
 202:       }
 203:       return { code: '', message: name.length > 0 ? name : 'error' };
 204:     }
 205: 
 206:     const obj = e as Record<string, string | number | boolean | object | undefined | null>;
 207:     const codeVal = obj['code'];
 208:     const messageVal = obj['message'];
 209:     const nameVal = obj['name'];
 210: 
 211:     const code = (typeof codeVal === 'string' || typeof codeVal === 'number') ? String(codeVal) : '';
 212:     const message = typeof messageVal === 'string' ? messageVal : '';
 213:     const name = typeof nameVal === 'string' ? nameVal : '';
 214:     const raw = this.safeJsonStringify(obj);
 215: 
 216:     if (code.length > 0 || message.length > 0) {
 217:       const title = name.length > 0 ? name : 'BusinessError';
 218:       const core = `${title}: ${message.length > 0 ? message : 'unknown'}`;
 219:       if (raw.length > 0) {
 220:         return { code, message: `${core} raw=${raw}` };
 221:       }
 222:       return { code, message: core };
 223:     }
 224:     if (raw.length > 0) {
 225:       return { code: '', message: raw };
 226:     }
 227:     return { code: '', message: 'unknown_error_object' };
 228:   }
 229: 
 230:   private safeJsonStringify(obj: Record<string, string | number | boolean | object | undefined | null>): string {
 231:     try {
 232:       const s = JSON.stringify(obj);
 233:       if (typeof s === 'string') {
 234:         return s;
 235:       }
 236:       return '';
 237:     } catch (e) {
 238:       return '';
 239:     }
 240:   }
 241: 
 242:   private newRequestId(): string {
 243:     const rand = Math.random().toString(36).substring(2, 8);
 244:     return `${Date.now()}_${rand}`;
 245:   }
 246: }
