 209: @Concurrent
 210: export async function executeDownload(params: DownloadTaskParams): Promise<DownloadTaskResult> {
 211:   console.info(`[WebDavSyncTask] Starting download in taskpool file=${params.remoteFile}`);
 212:   const startMs = Date.now();
 213: 
 214:   try {
 215:     // 创建 WebDAV 客户端
 216:     const client = new WebDavClient(params.endpoint, params.username, params.password);
 217: 
 218:     // 下载数据
 219:     console.info(`[WebDavSyncTask] Downloading from ${params.remoteFile}`);
 220:     const downloadStartMs = Date.now();
 221:     const getRes = await client.get(params.remoteFile);
 222:     const downloadMs = Date.now() - downloadStartMs;
 223:     
 224:     if (getRes.statusCode === 404) {
 225:       console.info(`[WebDavSyncTask] File not found (404): ${params.remoteFile}`);
 226:       const result: DownloadTaskResult = { success: true, data: '', detail: '文件不存在' };
 227:       return result;
 228:     }
 229:     if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
 230:       console.error(`[WebDavSyncTask] Download failed status=${getRes.statusCode} body=${getRes.body.substring(0, 200)}`);
 231:       const result: DownloadTaskResult = { success: false, data: '', detail: `GET ${getRes.statusCode}: ${getRes.body}` };
 232:       return result;
 233:     }
 234: 
 235:     console.info(`[WebDavSyncTask] Download complete size=${getRes.body.length} chars ms=${downloadMs}`);
 236: 
 237:     // 解密数据
 238:     let plain = '';
 239:     try {
 240:       console.info('[WebDavSyncTask] Decrypting downloaded data');
 241:       const decryptStartMs = Date.now();
 242:       plain = await WebDavCrypto.decryptUtf8Async(getRes.body, params.syncPassword);
 243:       const decryptMs = Date.now() - decryptStartMs;
 244:       console.info(`[WebDavSyncTask] Decryption complete plain_size=${plain.length} chars ms=${decryptMs}`);
 245:     } catch (ce) {
 246:       const errorMsg = ce instanceof CryptoError ? ce.message : String(ce);
 247:       console.error(`[WebDavSyncTask] Decryption failed: ${errorMsg}`);
 248:       if (ce instanceof Error && ce.stack) {
 249:         console.error(`[WebDavSyncTask] Decryption stack: ${ce.stack}`);
 250:       }
 251:       let userFriendlyMsg = errorMsg;
 252:       if (errorMsg.includes('MAC verification failed')) {
 253:         userFriendlyMsg = '同步密码错误或云端数据已损坏。建议：1)检查同步密码是否正确；2)点击"立即同步"重新上传本地数据覆盖云端';
 254:       }
 255:       const result: DownloadTaskResult = { success: false, data: '', detail: userFriendlyMsg };
 256:       return result;
 257:     }
 258: 
 259:     const totalMs = Date.now() - startMs;
 260:     console.info(`[WebDavSyncTask] Download task complete total_ms=${totalMs}`);
 261:     const successResult: DownloadTaskResult = { success: true, data: plain, detail: '' };
 262:     return successResult;
 263: 
 264:   } catch (e) {
 265:     const msg = e instanceof Error ? e.message : String(e);
 266:     const stack = e instanceof Error ? e.stack : '';
 267:     console.error(`[WebDavSyncTask] Download failed: ${msg}`);
 268:     if (stack) {
 269:       console.error(`[WebDavSyncTask] Stack trace: ${stack}`);
 270:     }
 271:     const errorResult: DownloadTaskResult = { success: false, data: '', detail: msg };
 272:     return errorResult;
 273:   }
 274: }
